def monitor_flag_rate(events):
    """The share of transcripts whose flagged value is True (SPEC section 1)."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event["flagged"] is True)
    return hits / len(events)


def pooled_flag_rate(groups):
    """The transcript-weighted flag rate across groups (SPEC section 2)."""
    total = sum(len(events) for events in groups.values())
    if total == 0:
        return 0.0
    hits = sum(
        1
        for events in groups.values()
        for event in events
        if event["flagged"] is True
    )
    return hits / total


def flags_in_window(daily_counts, days):
    """Sum the last ``days`` entries of daily counts (SPEC section 3)."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def flag_rate_by_group(groups):
    """The flag rate of each group (SPEC section 9)."""
    return {
        name: monitor_flag_rate(events) if events else None
        for name, events in sorted(groups.items())
    }


def longest_flag_streak(daily_counts):
    """Longest run of consecutive positive daily counts (SPEC section 10)."""
    best = cur = 0
    for count in daily_counts:
        if count > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""Load and normalize safety-monitor transcript logs."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped_line = line.strip()
        if not stripped_line or line.lstrip().startswith("#"):
            continue

        fields = line.split(",")
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day, flag = (field.strip() for field in fields)
        try:
            parsed_day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc

        if flag == "1":
            parsed_flag = True
        elif flag == "0":
            parsed_flag = False
        elif flag == "":
            parsed_flag = None
        else:
            raise ValueError(f"line {line_number}: flagged must be 1, 0, or empty")

        out.append({"id": id_, "day": parsed_day, "flagged": parsed_flag})
    return out


def dedupe_transcripts(events):
    """Keep the last record for each id, sorted by day and id (SPEC section 5)."""
    latest = {}
    for event in events:
        latest[event["id"]] = event
    return sorted(latest.values(), key=lambda event: (event["day"], event["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Count flagged transcripts for each inclusive day in a range (SPEC section 6)."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["flagged"] is True:
            counts[day - start_day] += 1
    return counts

