import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_counts_none_as_not_flagged():
    assert monitor_flag_rate(
        [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    ) == pytest.approx(1 / 3)


def test_monitor_flag_rate_empty():
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_uses_transcript_weights():
    groups = {
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_last_days():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2], 0) == 0
    assert flags_in_window([1, 2], 5) == 3


def test_parse_transcript_log_values_and_skipped_lines():
    assert parse_transcript_log(
        [" # header", "", " x1 , 3 , 1 ", "x2, 4, 0", "x3,5,"]
    ) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


@pytest.mark.parametrize("line", ["x,not-a-day,1", "x,1", "x,1,0,extra"])
def test_parse_transcript_log_invalid_lines_include_line_number(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# comment", line])


def test_dedupe_transcripts_keeps_last_record_for_duplicate_id():
    events = [
        {"id": "same", "day": 1, "flagged": True},
        {"id": "other", "day": 2, "flagged": False},
        {"id": "same", "day": 3, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[1], events[2]]


def test_daily_flag_counts_inclusive_range():
    events = [
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": None},
        {"day": 2, "flagged": True},
        {"day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 1]
    assert daily_flag_counts(events, 4, 2) == []


def test_monitor_summary_and_group_metrics():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
    ]
    assert monitor_summary({"g": events, "empty": []}, 1) == {
        "rate": 0.5,
        "recent": 0,
        "groups": 1,
    }
    assert flag_rate_by_group({"z": [], "b": [{"flagged": True}]}) == {
        "b": 1.0,
        "z": None,
    }
    assert top_flagged_groups(
        {"b": [{"flagged": True}], "a": [{"flagged": True}], "empty": []}, 1
    ) == ["a"]
    assert longest_flag_streak([1, 2, 0, 1]) == 2


